 "content": "def transform(grid):
    # The input is a texture made from repeated 2x2 macrotiles. The 6s hide
    # pieces which can be recovered by matching the same position in the
    # 2x2-periodic repeated motif across the visible grid.
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 6:
                candidates = [grid[rr][cc] for rr in range(h) for cc in range(w)
                              if grid[rr][cc] != 6 and rr % 2 == r % 2 and cc % 2 == c % 2]
                if candidates:
                    from collections import Counter
                    out[r][c] = Counter(candidates).most_common(1)[0][0]
    return out
