 "content": "def transform(grid):
    # Restore the masked texture by extending the 30x30 motif's periodic structure.
    # The colored background pattern repeats in a 30-cell frame; masked cells align
    # with corresponding positions in the visible repeated motif.
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # The mask itself covers a duplicate portion of the pattern: infer each location
    # from its nearest visible counterpart among translations by the repeated half-frame.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 6:
                continue
            candidates = []
            for dr in (-20, -10, 10, 20):
                rr = r + dr
                if 0 <= rr < h and grid[rr][c] != 6:
                    candidates.append(grid[rr][c])
            for dc in (-20, -10, 10, 20):
                cc = c + dc
                if 0 <= cc < w and grid[r][cc] != 6:
                    candidates.append(grid[r][cc])
            if candidates:
                out[r][c] = max(set(candidates), key=candidates.count)
    return out
