 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Inpaint each occluded cell by finding the closest matching visible patch.
    # Use known neighboring cells as a template, then let recovered cells guide
    # subsequent interior cells.
    for radius in (4, 3, 2, 1):
        for r in range(h):
            for c in range(w):
                if out[r][c] != 6:
                    continue
                best = None
                best_score = -1
                for rr in range(h):
                    for cc in range(w):
                        if grid[rr][cc] == 6:
                            continue
                        score = 0
                        total = 0
                        for dr in range(-radius, radius + 1):
                            for dc in range(-radius, radius + 1):
                                if dr == 0 and dc == 0:
                                    continue
                                ar, ac = r + dr, c + dc
                                br, bc = rr + dr, cc + dc
                                if 0 <= ar < h and 0 <= ac < w and 0 <= br < h and 0 <= bc < w:
                                    a = out[ar][ac]
                                    b = grid[br][bc]
                                    if a != 6 and b != 6:
                                        total += 1
                                        if a == b:
                                            score += 1
                        if total and score > best_score:
                            best_score, best = score, grid[rr][cc]
                if best is not None:
                    out[r][c] = best
    return out
