 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Find the closest matching local neighborhood elsewhere in the input. The
    # hidden cells are a patch copied from another location in this texture.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 6:
                continue
            best_value, best_score = 0, -1
            for rr in range(h):
                for cc in range(w):
                    if grid[rr][cc] == 6:
                        continue
                    score = 0
                    weight = 0
                    for dr in range(-4, 5):
                        for dc in range(-4, 5):
                            if dr == 0 and dc == 0:
                                continue
                            r1, c1, r2, c2 = r+dr, c+dc, rr+dr, cc+dc
                            if 0 <= r1 < h and 0 <= c1 < w and 0 <= r2 < h and 0 <= c2 < w:
                                a, b = grid[r1][c1], grid[r2][c2]
                                if a != 6 and b != 6:
                                    weight += 1
                                    score += (a == b)
                    if weight and score * (best_score if best_score > 0 else 1) > best_score * weight:
                        best_score = score / weight
                        best_value = grid[rr][cc]
            out[r][c] = best_value
    return out
