 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 6:
                continue
            candidates = []
            # Match rows by the visible cells outside the masked region.
            for rr in range(h):
                if rr == r or grid[rr][c] == 6:
                    continue
                overlap = [(j, grid[r][j], grid[rr][j]) for j in range(w)
                           if grid[r][j] != 6 and grid[rr][j] != 6]
                if overlap:
                    matches = sum(a == b for _, a, b in overlap)
                    candidates.append((matches / len(overlap), grid[rr][c]))
            # Match columns analogously.
            for cc in range(w):
                if cc == c or grid[r][cc] == 6:
                    continue
                overlap = [(i, grid[i][c], grid[i][cc]) for i in range(h)
                           if grid[i][c] != 6 and grid[i][cc] != 6]
                if overlap:
                    matches = sum(a == b for _, a, b in overlap)
                    candidates.append((matches / len(overlap), grid[r][cc]))
            if candidates:
                # Rank similarity and pool ties for robust repeated-pattern matching.
                top = max(score for score, _ in candidates)
                vals = [v for score, v in candidates if score >= top - 0.015]
                from collections import Counter
                out[r][c] = Counter(vals).most_common(1)[0][0]
    return out
