 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Infer regular repeated motifs from visible unmasked cells. For each hidden
    # cell, identify the translation vector giving best overall agreement among
    # visible pairs, then copy from that offset when possible.
    shifts = [(dr, dc) for dr in range(-15, 16) for dc in range(-15, 16) if (dr,dc)!=(0,0)]
    scores = []
    for dr, dc in shifts:
        same = total = 0
        for r in range(h):
            for c in range(w):
                rr, cc = r+dr, c+dc
                if 0 <= rr < h and 0 <= cc < w and grid[r][c] != 6 and grid[rr][cc] != 6:
                    total += 1
                    same += grid[r][c] == grid[rr][cc]
        if total:
            scores.append((same/total, total, dr, dc))
    scores.sort(reverse=True)
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 6:
                continue
            vals = []
            for _, _, dr, dc in scores[:30]:
                rr, cc = r+dr, c+dc
                if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] != 6:
                    vals.append(grid[rr][cc])
            if vals:
                from collections import Counter
                out[r][c] = Counter(vals).most_common(1)[0][0]
    return out
