 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 6:
                rr = h + 1 - r
                if rr >= h:
                    # The cropped upper edge continues the same reflected pattern.
                    rr = h - 1 - r
                if 0 <= rr < h and grid[rr][c] != 6:
                    out[r][c] = grid[rr][c]
                else:
                    # A nearby row continuation for edge cells where the exact
                    # reflected partner lies just beyond the cropped frame.
                    for d in range(1, h):
                        options = (r-d, r+d)
                        found = next((grid[y][c] for y in options if 0 <= y < h and grid[y][c] != 6), None)
                        if found is not None:
                            out[r][c] = found
                            break
    return out
