                # the nearest matching reflected pattern along the same row.
                for d in range(1, w):
                    options = (c-d, c+d, 32-(c-d), 32-(c+d))
                    found = next((grid[r][x] for x in options if 0 <= x < w and grid[r][x] != 6), None)
                    if found is not None:
                        out[r][c] = found
                        break
    return out
