 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for r in range(h):
        # Pick the row whose unmasked cells most closely match this row.
        vis = [c for c in range(w) if grid[r][c] != 6]
        ranked = []
        for rr in range(h):
            if rr == r:
                continue
            overlap = [c for c in vis if grid[rr][c] != 6]
            if overlap:
                ranked.append((sum(grid[r][c] == grid[rr][c] for c in overlap) / len(overlap), rr))
        ranked.sort(reverse=True)
        for c in range(w):
            if grid[r][c] != 6:
                continue
            for _, rr in ranked:
                if grid[rr][c] != 6:
                    out[r][c] = grid[rr][c]
                    break
            else:
                # use the nearest visible cell in that column
                for d in range(1, h):
                    for rr in (r-d, r+d):
                        if 0 <= rr < h and grid[rr][c] != 6:
                            out[r][c] = grid[rr][c]
                            break
                    if out[r][c] != 6:
                        break
    return out
